import { test, expect } from '@playwright/test';

test.describe('Search Field Dropdown - Matching Options', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should display matching options dropdown when user types in search field', async ({ page }) => {
    // Locate search input using getByLabel
    const searchInput = page.getByLabel('Search');
    await expect(searchInput).toBeVisible();

    // Type a partial search term
    await searchInput.fill('apple');

    // Wait for dropdown to appear
    await page.waitForSelector('[data-testid="search-dropdown"]');
    const dropdown = page.locator('[data-testid="search-dropdown"]');
    await expect(dropdown).toBeVisible();

    // Verify dropdown contains matching options
    const options = page.locator('[data-testid="search-option"]');
    await expect(options).toHaveCount(2);

    // Verify option text
    const firstOption = page.locator('[data-testid="search-option"]').first();
    await expect(firstOption).toContainText('Apple');

    const secondOption = page.locator('[data-testid="search-option"]').nth(1);
    await expect(secondOption).toContainText('Apple Pie');

    // Select the first option
    await firstOption.click();

    // Verify search input is populated with selected value
    await expect(searchInput).toHaveValue('Apple');
  });

  test('should not display dropdown when search term does not match any options', async ({ page }) => {
    // Locate search input using getByLabel
    const searchInput = page.getByLabel('Search');
    await expect(searchInput).toBeVisible();

    // Type a non-existent search term
    await searchInput.fill('xyz123');

    // Wait briefly and verify dropdown does not appear
    await page.waitForTimeout(100);
    const dropdown = page.locator('[data-testid="search-dropdown"]');
    await expect(dropdown).not.toBeVisible();

    // Verify search input is empty or unchanged
    await expect(searchInput).toHaveValue('xyz123');

    // Clear the search input
    await searchInput.clear();

    // Verify dropdown remains hidden
    await expect(dropdown).not.toBeVisible();
  });
});
